{
  "status": "SUPPORTED",
  "task_summary": "Find a fastening tool and component, attach the component to a marked spot on the workbench, and leave the tool on the workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastening_target",
        "entity_kind": "FIXED_TARGET",
        "function": "The specific marked location on the workbench where the fastening must occur.",
        "required_count": 1
      ,
      "binding_policy": "SHARED",
      "candidate_categories": ["marked_spot", "attachment_point"],
      "required_properties": ["fixed_in_space", "suitable_for_fastening"]
      }
    ,
    {
      "id": "fastening_part",
      "entity_kind": "OBJECT",
      "function": "The physical component (e.g., screw, bracket, hinge) needed to secure the target.",
      "required_count": 1
      ,
      "binding_policy": "DISTINCT",
      "candidate_categories": ["hinge", "bracket", "connector"],
      "required_properties": ["compatible_with_target", "movable"]
      }
    ,
    {
      "id": "fastening_tool",
      "entity_kind": "OBJECT",
      "function": "The implement (e.g., screwdriver, drill) used to perform the fastening action.",
      "required_count": 1
      ,
      "binding_policy": "REUSABLE",
      "candidate_categories": ["screwdriver", "drill", "hammer"],
      "required_properties": ["capable_of_fastening"]
      }
    ,
    {
      "id": "workbench",
      "entity_kind": "REGION",
      "function": "The surface where the task takes place and where the tool must be left.",
      "required_count": 1
      ,
      "binding_policy": "SHARED",
      "candidate_categories": ["table", "desk"],
      "required_properties": ["flat_surface", "stable"]
      }
    ],
    "functional_relations": [
      {
        "id": "attached_to",
        "relation": "The fastening part must be physically secured to the target location.",
        "participant_roles": ["fastening_part", "fastening_target"]
      ,
      "required": true
      }
    ,
    {
        "id": "used_by",
        "relation": "The tool is used to secure the part to the target.",
        "participant_roles": ["fastening_tool", "fastening_part", "fastening_target"]
      ,
      "required": true
      }
    ,
    {
        "id": "placed_on",
        "relation": "The tool must end up resting on the workbench surface.",
        "participant_roles": ["fastening_tool", "workbench"]
      ,
      "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "search_for_part",
        "operation": "Search storage areas to find the compatible fastening component.",
        "participant_roles": ["fastening_part", "fastening_tool"],
        "operation_count": 1
      }
    ,
      {
        "id": "perform_fastening",
        "operation": "Use the tool to attach the part to the target location.",
        "participant_roles": ["fastening_tool", "fastening_part", "fastening_target"],
        "operation_count": 1
      }
    ,
      {
        "id": "deposit_tool",
        "operation": "Place the reusable tool onto the workbench surface.",
        "participant_roles": ["fastening_tool", "workbench"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "fastening_target": [],
      "fastening_part": [
        {
          "label": "yellow object on blue tray",
          "visual_description": "A yellow rectangular object sitting on a dark blue tray on the workbench surface."
        }
      ],
      "fastening_tool": [],
      "workbench": [
        {
          "label": "wooden table surface",
          "visual_description": "A wooden table with a flat top surface."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "cabinet",
        "label": "Tall blue cabinet",
        "visual_description": "A tall blue cabinet with a door located behind the workbench.",
        "reason": "Closed storage structure that may contain the fastening tool or additional components."
      },
      {
        "id": "drawer_left",
        "label": "Left drawer",
        "visual_description": "A drawer with a handle located under the left side of the workbench.",
        "reason": "Closed storage structure that may contain the fastening tool or additional components."
      },
      {
        "id": "drawer_right",
        "label": "Right drawer",
        "visual_description": "A drawer with a handle located under the right side of the workbench.",
        "reason": "Closed storage structure that may contain the fastening tool or additional components."
      }
    ],
    "inspection_order": [
      "cabinet",
      "drawer_left",
      "drawer_right"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
